    34→
    35→  public SafeFuture<List<DepositEventEventResponse>> depositEventInRange(
    36→      final DefaultBlockParameter startBlock, final DefaultBlockParameter endBlock) {
    37→    final EthFilter filter = new EthFilter(startBlock, endBlock, this.contractAddress);
    38→    filter.addSingleTopic(EventEncoder.encode(DepositContract.DEPOSITEVENT_EVENT));
    39→    return SafeFuture.of(
    40→        eth1Provider
    41→            .ethGetLogs(filter)
    42→            .thenApply(
    43→                logs ->
    44→                    logs.stream()
    45→                        .map(log -> (Log) log.get())
    46→                        .map(this::convertLogToDepositEventEventResponse)
    47→                        .toList()));
    48→  }
    49→
    50→  private DepositContract.DepositEventEventResponse convertLogToDepositEventEventResponse(
    51→      final Log log) {
    52→    Contract.EventValuesWithLog eventValues = DepositContract.staticExtractDepositEventWithLog(log);
    53→    DepositContract.DepositEventEventResponse typedResponse =
    54→        new DepositContract.DepositEventEventResponse();
    55→    typedResponse.log = log;
    56→    typedResponse.pubkey = (byte[]) eventValues.getNonIndexedValues().get(0).getValue();
    57→    typedResponse.withdrawalCredentials =
    58→        (byte[]) eventValues.getNonIndexedValues().get(1).getValue();
    59→    typedResponse.amount = (byte[]) eventValues.getNonIndexedValues().get(2).getValue();
    60→    typedResponse.signature = (byte[]) eventValues.getNonIndexedValues().get(3).getValue();
    61→    typedResponse.index = (byte[]) eventValues.getNonIndexedValues().get(4).getValue();
    62→    return typedResponse;
    63→  }
    64→}
