   676→  private boolean batchVerifyDepositSignatures(final SszList<Deposit> deposits) {
   677→    try {
   678→      final List<List<BLSPublicKey>> publicKeys = new ArrayList<>();
   679→      final List<Bytes> messages = new ArrayList<>();
   680→      final List<BLSSignature> signatures = new ArrayList<>();
   681→      for (final Deposit deposit : deposits) {
   682→        final BLSPublicKey pubkey = deposit.getData().getPubkey();
   683→        publicKeys.add(List.of(pubkey));
   684→        messages.add(
   685→            miscHelpers.computeDepositSigningRoot(
   686→                pubkey,
   687→                deposit.getData().getWithdrawalCredentials(),
   688→                deposit.getData().getAmount()));
   689→        signatures.add(deposit.getData().getSignature());
   690→      }
   691→      // Overwhelmingly often we expect all the deposit signatures to be good
   692→      return specConfig.getBLSSignatureVerifier().verify(publicKeys, messages, signatures);
   693→    } catch (final BlsException e) {
   694→      return false;
   695→    }
   696→  }
