   735→  /** apply_deposit */
   736→  public void applyDeposit(
   737→      final MutableBeaconState state,
   738→      final BLSPublicKey pubkey,
   739→      final Bytes32 withdrawalCredentials,
   740→      final UInt64 amount,
   741→      final BLSSignature signature,
   742→      final Optional<Object2IntMap<BLSPublicKey>> maybePubkeyToIndexMap,
   743→      final boolean signatureAlreadyVerified) {
   744→    // Find the validator index associated with this deposit, if it exists
   745→    final Optional<Integer> existingIndex =
   746→        maybePubkeyToIndexMap
   747→            .flatMap(
   748→                pubkeyToIndexMap -> {
   749→                  if (pubkeyToIndexMap.containsKey(pubkey)) {
   750→                    return Optional.of(pubkeyToIndexMap.getInt(pubkey));
   751→                  } else {
   752→                    pubkeyToIndexMap.put(pubkey, state.getValidators().size());
   753→                    return Optional.empty();
   754→                  }
   755→                })
   756→            .or(() -> validatorsUtil.getValidatorIndex(state, pubkey));
   757→
   758→    if (existingIndex.isEmpty()) {
   759→      // This is a new validator
   760→      // Verify the deposit signature (proof of possession) which is not checked by the deposit
   761→      // contract
   762→      if (signatureAlreadyVerified
   763→          || miscHelpers.isValidDepositSignature(
   764→              pubkey, withdrawalCredentials, amount, signature)) {
   765→        beaconStateMutators.addValidatorToRegistry(state, pubkey, withdrawalCredentials, amount);
   766→      } else {
   767→        handleInvalidDeposit(pubkey, maybePubkeyToIndexMap);
   768→      }
   769→    } else {
   770→      // Increase balance by deposit amount
   771→      beaconStateMutators.increaseBalance(state, existingIndex.get(), amount);
   772→    }
   773→  }
