    31→
    32→  protected DepositsFromBlockEvent(
    33→      final UInt64 blockNumber,
    34→      final Bytes32 blockHash,
    35→      final UInt64 blockTimestamp,
    36→      final List<Deposit> deposits) {
    37→    assertDepositsValid(deposits);
    38→    this.blockTimestamp = blockTimestamp;
