    43→
    44→  protected void assertDepositsValid(final List<Deposit> deposits) {
    45→    checkArgument(!deposits.isEmpty(), "Attempting to notify no events in a block");
    46→    if (deposits.size() <= 1) {
    47→      return;
    48→    }
    49→
    50→    UInt64 previousIndex = deposits.get(0).getMerkle_tree_index();
    51→    for (int i = 1; i < deposits.size(); i++) {
    52→      UInt64 currentIndex = deposits.get(i).getMerkle_tree_index();
    53→      if (!previousIndex.plus(1).equals(currentIndex)) {
    54→        final String error =
    55→            String.format(
    56→                "Deposits must be ordered and contiguous. Deposit at index %s does not follow prior deposit at index %s",
    57→                currentIndex, previousIndex);
    58→        throw new InvalidDepositEventsException(error);
    59→      }
    60→      previousIndex = currentIndex;
    61→    }
    62→  }
